import json

# Board: 64 chars, index = (7-rank)*8 + file  (a8 first, h1 last)
def sq(f, r):
    return (7 - r) * 8 + f

def name(f, r):
    return "abcdefgh"[f] + str(r + 1)

def onb(f, r):
    return 0 <= f < 8 and 0 <= r < 8

rules = []

# ---------- 1. normalise input ----------
rules.append([r" \d+ \d+$", ""])
for d in range(8, 0, -1):
    rules.append([str(d) + r"(?=[^ ]* )", "." * d])
rules.append([r"/(?=[^ ]* )", ""])

# ---------- 2. move generation ----------
TARGET = "[.pnbrq]"

def tags_for(s, t):
    tg = set()
    for x in (s, t):
        if x == sq(4, 0):
            tg |= {"K", "Q"}
        if x == sq(7, 0):
            tg.add("K")
        if x == sq(0, 0):
            tg.add("Q")
        if x == sq(7, 7):
            tg.add("k")
        if x == sq(0, 7):
            tg.add("q")
    return "".join(c for c in "KQkq" if c in tg)

def emit(constraints, changes, tags, ep="-", extra=""):
    """constraints: {pos: regex class}; changes: {pos: newchar}"""
    pat = r"\A"
    for p in sorted(constraints):
        pat += "(?=.{%d}%s)" % (p, constraints[p]) if p else "(?=%s)" % constraints[p]
    pat += extra
    cs = sorted(changes)
    repl_board = ""
    prev = 0
    g = 0
    for c in cs:
        pat += "(.{%d})." % (c - prev)
        g += 1
        repl_board += "\\g<%d>" % g + changes[c].replace("\\", "\\\\")
        prev = c + 1
    pat += "(.{%d})" % (64 - prev)
    g += 1
    repl_board += "\\g<%d>" % g
    pat += r" w ([^ ]*) ([^ \n]*)"
    castg = g + 1
    repl = "\\g<0>\n" + repl_board + " b \\g<%d> %s :%s" % (castg, ep, tags)
    rules.append([pat, repl])

def move(s, t, piece, path, newpiece=None, ep="-"):
    cons = {s: piece, t: TARGET}
    for p in path:
        cons[p] = r"\."
    emit(cons, {s: ".", t: newpiece or piece}, tags_for(s, t), ep)

ROOK = [(1, 0), (-1, 0), (0, 1), (0, -1)]
BISH = [(1, 1), (1, -1), (-1, 1), (-1, -1)]
KNIGHT = [(1, 2), (2, 1), (-1, 2), (-2, 1), (1, -2), (2, -1), (-1, -2), (-2, -1)]
KING = ROOK + BISH

for f in range(8):
    for r in range(8):
        s = sq(f, r)
        for piece, dirs in (("Q", KING), ("R", ROOK), ("B", BISH)):
            for df, dr in dirs:
                path = []
                ff, rr = f + df, r + dr
                while onb(ff, rr):
                    move(s, sq(ff, rr), piece, path)
                    path.append(sq(ff, rr))
                    ff += df
                    rr += dr
        for df, dr in KNIGHT:
            if onb(f + df, r + dr):
                move(s, sq(f + df, r + dr), "N", [])
        for df, dr in KING:
            if onb(f + df, r + dr):
                move(s, sq(f + df, r + dr), "K", [])
        # pawns
        if 1 <= r <= 6:
            promo = "Q" if r == 6 else None
            t = sq(f, r + 1)
            emit({s: "P", t: r"\."}, {s: ".", t: promo or "P"}, tags_for(s, t))
            if r == 1:
                t2 = sq(f, 3)
                emit({s: "P", t: r"\.", t2: r"\."}, {s: ".", t2: "P"}, "", ep=name(f, 2))
            for df in (-1, 1):
                if onb(f + df, r + 1):
                    t = sq(f + df, r + 1)
                    emit({s: "P", t: "[pnbrq]"}, {s: ".", t: promo or "P"}, tags_for(s, t))
            if r == 4:
                for df in (-1, 1):
                    if onb(f + df, r + 1):
                        t = sq(f + df, 5)
                        cap = sq(f + df, 4)
                        emit({s: "P", t: r"\.", cap: "p"}, {s: ".", t: "P", cap: "."}, "",
                             extra=r"(?=.{64} w [^ ]* %s(?:\n|$))" % name(f + df, 5))

# castling (X = phantom king square becoming empty, Y = phantom becoming rook)
e1, f1, g1, h1, d1, c1, b1, a1 = (sq(i, 0) for i in (4, 5, 6, 7, 3, 2, 1, 0))
emit({e1: "K", f1: r"\.", g1: r"\.", h1: "R"}, {e1: "X", f1: "Y", g1: "K", h1: "."}, "KQ",
     extra=r"(?=.{64} w [^ ]*K)")
emit({e1: "K", d1: r"\.", c1: r"\.", b1: r"\.", a1: "R"}, {e1: "X", d1: "Y", c1: "K", a1: "."}, "KQ",
     extra=r"(?=.{64} w [^ ]*Q)")

# ---------- 3. legality filter ----------
def la(p, cls):
    return "(?=.{%d}%s)" % (p, cls) if p else "(?=%s)" % cls

for f in range(8):
    for r in range(8):
        k = sq(f, r)
        alts = []
        for dirs, att in ((ROOK, "[rq]"), (BISH, "[bq]")):
            for df, dr in dirs:
                path = []
                ff, rr = f + df, r + dr
                while onb(ff, rr):
                    alts.append("".join(la(p, r"\.") for p in path) + la(sq(ff, rr), att))
                    path.append(sq(ff, rr))
                    ff += df
                    rr += dr
        for df, dr in KNIGHT:
            if onb(f + df, r + dr):
                alts.append(la(sq(f + df, r + dr), "n"))
        for df, dr in KING:
            if onb(f + df, r + dr):
                alts.append(la(sq(f + df, r + dr), "k"))
        for df in (-1, 1):
            if onb(f + df, r + 1):
                alts.append(la(sq(f + df, r + 1), "p"))
        pat = r"\n(?=.{64} b )" + la(k, "[KXY]") + "(?:" + "|".join(alts) + r")[^\n]*"
        rules.append([pat, ""])

# ---------- 4. cleanup ----------
rules.append(["X", "."])
rules.append(["Y", "R"])
for c in "KQkq":
    rules.append([r"(?m)^(.{64} b [^ ]*?)%s(?=[^ ]* [^ ]+ :[A-Za-z]*%s)" % (c, c), r"\1"])
rules.append([r" :[A-Za-z]*", ""])
rules.append([r"(?m)^(.{64} b) (?= )", r"\1 -"])
rules.append([r"\A[^\n]*\n?", ""])
rules.append([r"(?m)^" + "(.{8})" * 8 + "(?= b)", "/".join("\\%d" % i for i in range(1, 9))])
for d in range(8, 0, -1):
    rules.append([r"\." * d, str(d)])
rules.append([r"(?m)$", " 0 0"])

json.dump(rules, open("/tmp/obench-cell-x3i5jmf3/bench_opencode_regex-chess_w83v2825/re.json", "w"))
print(len(rules))
